N = 2017
two_N = 2 * N

def theoretical_upper_bound(K):
    return N * (two_N / K)

K_values = [65, 66, 70]
print("K | Theoretical Upper Bound (N * 2N/K)")
for K in K_values:
    bound = theoretical_upper_bound(K)
    print(f"{K} | {bound:.2f}")
